+    }
+    remainder = normalize::strip(&remainder);
+    remainder = data::patterns()
+        .punctuation
+        .replace_all(&remainder, " ")
+        .trim()
+        .into();
+    let penalty = if remainder.chars().any(|c| c.is_alphanumeric()) {
