+    /^[a-z]+(?: [a-z]+)*$/.test(e.text) &&
+    !e.ambiguous &&
+    e.kind !== "abbreviation"
+  ) {
+    const size = e.text.split(" ").length;
+    typoByLength.set(size, [...(typoByLength.get(size) ?? []), e]);
+  }
+}

